byid['10-07']['instruction']='เมื่อเลื่อนเหนือฐาน ระบบยก Z อัตโนมัติ หากวางเหลื่อมยังคงแสดงด้านบนแต่มีขอบและข้อความเตือนสีแดง ต้องให้พาเลทอยู่บนฐานเต็มพื้นที่ก่อนยืนยัน'
manifest={'title':'คู่มือใช้งาน Storage Planner','subtitle':'ทำตามจากภาพหน้าจอจริงทีละขั้นตอน กรอบสีแดงและหมายเลขชี้จุดใช้งาน ทุกภาพแสดงในหน้านี้ทันที ไม่ต้องคลิกเปิดภาพ','date':'7 กันยายน 2026','lang':'th','chapters':[]}
for prefix,title,intro in chapters:
 manifest['chapters'].append({'id':'chapter-'+prefix,'title':title,'intro':intro,'steps':sorted([s for s in captures if s['id'].startswith(prefix+'-')],key=lambda s:s['id'])})
(root/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
with (root/'coverage.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['chapter','step','title','image','capture_url','status'])
 for ch in manifest['chapters']:
  for s in ch['steps']:w.writerow([ch['id'],s['id'],s['title'],s['image'],s['url'],'captured'])
print('Assembled',len(captures),'steps in',len(chapters),'chapters')
